{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear which family members are involved in the caregiving schedule and what their specific roles or availability constraints are.",
      "why_it_matters": "Knowing who participates and in what capacity is essential to model the workflow accurately and identify which steps require human coordination versus automation."
    },
    {
      "category": "input",
      "gap": "There is no description of how availability information is collected from each family member before the schedule is drafted.",
      "why_it_matters": "The method of collecting availability (e.g., verbal, text message, shared calendar) determines what data sources exist and whether they can be integrated or automated."
    },
    {
      "category": "output",
      "gap": "The format and medium through which the finalized schedule is communicated to all family members is not specified.",
      "why_it_matters": "Understanding the output format (e.g., printed chart, group chat message, shared app) is necessary to assess automation of schedule distribution and notification."
    },
    {
      "category": "decision",
      "gap": "The criteria or priority rules used to find an alternative arrangement when someone cannot make their slot are not described.",
      "why_it_matters": "Decision logic for substitutions is a key automation target; without it, the exception-handling path cannot be modeled or partially automated."
    },
    {
      "category": "exception",
      "gap": "It is unclear what happens if no alternative arrangement can be found for a given slot (i.e., escalation or fallback when all options are exhausted).",
      "why_it_matters": "Edge cases where coverage fails need a defined resolution path to ensure the workflow is complete and to assess risk."
    },
    {
      "category": "frequency",
      "gap": "The specific day and time each week when the scheduling process is initiated and must be completed is not stated.",
      "why_it_matters": "Timing constraints determine scheduling deadlines, reminder automation opportunities, and how much lead time exists for handling exceptions."
    },
    {
      "category": "system",
      "gap": "No tools or platforms currently used to coordinate the schedule (e.g., paper, messaging app, shared calendar) are mentioned.",
      "why_it_matters": "Existing tools define integration constraints and the baseline for any automation or digitization effort."
    },
    {
      "category": "manual_effort",
      "gap": "The amount of back-and-forth communication required to resolve a scheduling conflict is not quantified or described.",
      "why_it_matters": "Understanding the effort involved in conflict resolution helps prioritize which parts of the workflow would benefit most from automation."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Who are the family members involved in the caregiving schedule, and does each person have a fixed role (e.g., primary caregiver, backup) or does the role vary week to week?",
      "targets": ["actor"]
    },
    {
      "id": "Q2",
      "question": "How do family members currently share their availability with you before you draft the schedule — for example, do they message you individually, fill in a shared calendar, or tell you verbally?",
      "targets": ["input", "system"]
    },
    {
      "id": "Q3",
      "question": "On which day of the week does the scheduling process typically start, and by when does the final schedule need to be agreed upon?",
      "targets": ["frequency"]
    },
    {
      "id": "Q4",
      "question": "When someone says they cannot make their slot, what is the process for finding a replacement — do you contact other family members in a specific order, or is it whoever responds first?",
      "targets": ["decision"]
    },
    {
      "id": "Q5",
      "question": "What happens if no family member is available to cover a slot after you have tried to find an alternative — is there a fallback option such as external childcare or postponing the activity?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "Once the schedule is finalized or updated, how is it shared with everyone — for example, sent as a message in a group chat, posted somewhere visible, or communicated individually?",
      "targets": ["output"]
    }
  ]
}
